import {rigMatrices} from './sprite-rig-assets.js';
function chainTo(bones,from,to,occupied,children){const result=[];for(let node=bones.get(to);node;node=bones.get(node.parent)){result.push(node);if(node.id===from){result.reverse();if(result.slice(1,-1).some(b=>occupied.has(b.id)||(children.get(b.id)||0)>1))return null;return result;}if(result.length>1&&occupied.has(node.id))return null;}return null;}
function fractions(chain,matrices){const distances=[0];let sum=0;for(let i=1;i<chain.length;i++){const a=matrices.get(chain[i-1].id),b=matrices.get(chain[i].id);sum+=Math.hypot(b[4]-a[4],b[5]-a[5])||Math.hypot(a[0],a[1])*chain[i-1].length;distances.push(sum);}return chain.slice(1,-1).map((bone,i)=>({id:bone.id,fraction:distances[i+1]/sum}));}
// Maximal one-to-one monotone matching; among equally sized matches minimize
// rest-chain arc error. Skip ties keep the earlier authored candidate.
function align(a,b){if(!a.length||!b.length)return[];const swap=a.length>b.length,short=swap?b:a,long=swap?a:b,m=short.length,n=long.length,cost=Array.from({length:m+1},()=>new Float64Array(n+1).fill(Infinity)),take=Array.from({length:m+1},()=>new Uint8Array(n+1));cost[0].fill(0);for(let i=1;i<=m;i++)for(let j=1;j<=n;j++){const match=cost[i-1][j-1]+(short[i-1].fraction-long[j-1].fraction)**2,skip=cost[i][j-1];if(match<skip){cost[i][j]=match;take[i][j]=1;}else cost[i][j]=skip;}const result=[];for(let i=m,j=n;i&&j;j--)if(take[i][j]){const small=short[--i].id,big=long[j-1].id;result.push(swap?{source:big,target:small}:{source:small,target:big});}return result.reverse();}
export function mapSpriteRigChains(source,target,anchors){
 const sources=new Map(source.bones.map(b=>[b.id,b])),targets=new Map(target.bones.map(b=>[b.id,b])),seed=new Map(anchors.map(p=>[p.source,p.target])),pairs=new Map(seed),used=new Set(seed.values()),sc=new Map(),tc=new Map();for(const [rig,counts]of [[source,sc],[target,tc]])for(const b of rig.bones)counts.set(b.parent,(counts.get(b.parent)||0)+1);const sm=rigMatrices(source),tm=rigMatrices(target);
 for(const [end,to]of seed){let parent=sources.get(end).parent;while(parent&&!seed.has(parent))parent=sources.get(parent).parent;if(!parent)continue;const a=chainTo(sources,parent,end,new Set(seed.keys()),sc),b=chainTo(targets,seed.get(parent),to,used,tc);if(!a||!b)continue;for(const row of align(fractions(a,sm),fractions(b,tm))){if(pairs.has(row.source)||used.has(row.target))continue;pairs.set(row.source,row.target);used.add(row.target);}}
 const depth=id=>{let n=sources.get(id),value=0;while(n.parent){value++;n=sources.get(n.parent);}return value;};return [...pairs].sort((a,b)=>depth(a[0])-depth(b[0])).map(([source,target])=>({source,target}));
}